<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';import ContextMenu from 'primevue/contextmenu';import Button from 'primevue/button';import InputText from 'primevue/inputtext';import OSWindow from './components/OSWindow.vue';import {useOS} from './store';
const os=useOS(),menu=ref(null),target=ref(null),search=ref(''),now=ref(new Date());let interval,timer,start,held=false;
const mobile=ref(matchMedia('(max-width: 640px)').matches),switcher=ref(false);const media=matchMedia('(max-width: 640px)');function modeChanged(e){mobile.value=e.matches;switcher.value=false}onMounted(()=>media.addEventListener('change',modeChanged));onBeforeUnmount(()=>media.removeEventListener('change',modeChanged));
function home(){switcher.value=false;os.showDesktop()}function resume(win){switcher.value=false;win.minimized=false;os.focus(win.id)}
const apps=computed(()=>os.apps.filter(a=>a.title.toLowerCase().includes(search.value.toLowerCase())));
const menuItems=computed(()=>target.value?[{label:'開啟',icon:'pi pi-external-link',command:()=>os.open(target.value.id)},...(!mobile.value?[{label:'開啟新視窗',icon:'pi pi-clone',command:()=>os.open(target.value.id,true)}]:[]),{label:os.dock.includes(target.value.id)?'從 Dock 移除':'加入 Dock',icon:'pi pi-thumbtack',command:()=>os.pin(target.value.id)},...(target.value.kind==='component'?[{separator:true},{label:'管理此組件',icon:'pi pi-pencil',command:()=>os.open('manager')}]:[])]:[{label:mobile.value?'返回主畫面':'顯示桌面',icon:'pi pi-desktop',command:()=>home()},{label:'組件管理',icon:'pi pi-box',command:()=>os.open('manager')},{label:'桌面設定',icon:'pi pi-cog',command:()=>os.open('settings')},{label:'重新載入組件',icon:'pi pi-refresh',command:()=>os.load()}]);
function context(e,app=null){e.preventDefault();target.value=app;menu.value.show(e)}
function cancel(){clearTimeout(timer)}
function down(e,app=null){held=false;cancel();if(e.pointerType==='mouse')return;start={x:e.clientX,y:e.clientY};timer=setTimeout(()=>{held=true;context({preventDefault(){},pageX:e.pageX,pageY:e.pageY,clientX:e.clientX,clientY:e.clientY},app)},550)}
function move(e){if(start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>10)cancel()}
function launch(app){cancel();if(held){held=false;return}os.open(app.id)}
function key(e){if(e.key==='Escape'){menu.value.hide();cancel()}if(e.altKey&&e.key==='d'){e.preventDefault();os.showDesktop()}}
onMounted(()=>{os.load();interval=setInterval(()=>now.value=new Date(),1000);window.addEventListener('keydown',key)});onBeforeUnmount(()=>{clearInterval(interval);cancel();window.removeEventListener('keydown',key)});
</script>
<template><main :class="['desktop',os.wallpaper]" @contextmenu.self="context($event)" @pointerdown.self="down($event)" @pointerup="cancel" @pointercancel="cancel" @pointermove="move">
 <header class="menubar"><button class="brand" @click="os.showDesktop()"><span class="brand-mark">O</span><b>OlitGlobal</b><span class="brand-sub">Web OS</span></button><div class="status-bar"><span class="status-dot"></span><span class="status-label">{{os.error?'連線異常':'工作空間'}}</span><i class="pi pi-wifi"></i><time>{{now.toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit',hour12:false})}}</time></div></header>
 <div class="desktop-content" @contextmenu.self="context($event)" @pointerdown.self="down($event)"><div class="desktop-heading justify-end"><div class="search-box"><i class="pi pi-search"></i><InputText v-model="search" placeholder="搜尋 APP" aria-label="搜尋 APP"/></div></div>
 <div v-if="os.loading" class="notice" role="status">正在載入工作空間…</div><div v-else-if="os.error" class="notice" role="alert">{{os.error}} <Button label="重試" @click="os.load()"/></div>
 <template v-else><div class="workspace-summary"><div><i class="pi pi-sparkles"></i><b>今天的工作空間</b><span>{{os.config?.components.length}} 個組件，隨時開啟。</span><small>示意資料</small></div></div>
 <div class="app-grid"><button v-for="app in apps" :key="app.id" :data-testid="'app-'+app.id" class="app-icon" @click="launch(app)" @contextmenu.stop="context($event,app)" @pointerdown.stop="down($event,app)" @keydown.shift.f10.prevent="context($event,app)"><span :class="['icon-tile',app.color]"><i :class="['pi',app.icon]"></i><span v-if="app.id==='alerts'" class="badge">{{app.data.value}}</span></span><span class="icon-title">{{app.title}}</span><span v-if="os.windows.some(w=>w.appId===app.id)" class="running-dot"></span></button></div><p v-if="!apps.length" class="notice">找不到符合的 APP</p>
 <div class="desktop-footer"><span><i class="pi pi-mouse"></i> 右鍵 / 長按開啟操作選單</span><span>OLITGLOBAL WORKSPACE / 01</span></div></template></div>
 <OSWindow v-for="win in os.windows" :key="win.id" :win="win"/>
 <nav v-show="!mobile || (!os.active && !switcher)" class="dock" aria-label="Dock"><button v-if="!mobile" aria-label="顯示桌面" class="dock-home" @click="home()"><i class="pi pi-th-large"></i></button><span v-if="!mobile" class="dock-divider"></span><button v-for="app in os.dockApps" :key="app.id" :aria-label="'Dock '+app.title" class="dock-item" @click="launch(app)" @contextmenu.stop="context($event,app)" @pointerdown.stop="down($event,app)"><span :class="['icon-tile',app.color]"><i :class="['pi',app.icon]"></i></span><span class="dock-tooltip">{{app.title}}</span><span v-if="!mobile && os.windows.some(w=>w.appId===app.id)" class="running-dot"></span></button><template v-if="!mobile && os.windows.length"><span class="dock-divider"></span><button v-for="win in os.windows" :key="win.id" :aria-label="'切換視窗 '+win.id" :class="['task-item',{selected:os.active?.id===win.id}]" @click="resume(win)">{{win.id}}</button></template></nav>
 <section v-if="mobile && switcher" class="iphone-switcher" aria-label="最近 APP"><header><h2>最近 APP</h2><button aria-label="返回主畫面" @click="home()">完成</button></header><p v-if="!os.windows.length">尚未開啟 APP</p><div class="recent-grid"><article v-for="win in [...os.windows].sort((a,b)=>b.z-a.z)" :key="win.id"><button class="recent-app" :aria-label="'返回 '+os.apps.find(a=>a.id===win.appId)?.title" @click="resume(win)"><span :class="['icon-tile',os.apps.find(a=>a.id===win.appId)?.color]"><i :class="['pi',os.apps.find(a=>a.id===win.appId)?.icon]"></i></span><b>{{os.apps.find(a=>a.id===win.appId)?.title}}</b></button><button class="recent-close" :aria-label="'結束 '+os.apps.find(a=>a.id===win.appId)?.title" @click="os.close(win.id)"><i class="pi pi-times"></i></button></article></div></section>
 <nav v-if="mobile" :class="['iphone-navigation',{'in-app':os.active && !switcher}]" aria-label="iPhone 導覽"><button class="recent-trigger" aria-label="顯示最近 APP" @click="switcher=!switcher"><i class="pi pi-clone"></i></button><button class="home-indicator" aria-label="返回主畫面" @click="home()"><span></span></button></nav>
 <ContextMenu ref="menu" :model="menuItems" :pt="{root:{'data-testid':'desktop-context'}}"/>
</main></template>
